import{_ as o,a0 as l,w as m,s as p,ao as r,I as e,x as n,a1 as t,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"RHCE 系列（六）：安裝 Samba 並配置 Firewalld 和 SELinux 讓 Linux 和 Windows 共享文件 | LCTT x X-CMD","titleTemplate":false,"description":"RHCE 系列（六）：安裝 Samba 並配置 Firewalld 和 SELinux 讓 Linux 和 Windows 共享文件 | LCTT (RHCE) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCE 系列（六）：安裝 Samba 並配置 Firewalld 和 SELinux 讓 Linux 和 Windows 共享文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCE 系列（六）：安裝 Samba 並配置 Firewalld 和 SELinux 讓 Linux 和 Windows 共享文件 | LCTT (RHCE) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCE/Part 6 - Setting Up Samba and Configure FirewallD and SELinux to Allow File Sharing on Linux or Windows Clients","title":"RHCE 系列（六）：安裝 Samba 並配置 Firewalld 和 SELinux 讓 Linux 和 Windows 共享文件","tag":"RHCE","desc":""},"relativePath":"RHCE/Part 6 - Setting Up Samba and Configure FirewallD and SELinux to Allow File Sharing on Linux or Windows Clients.md","filePath":"[post].md"}'),d={name:"RHCE/Part 6 - Setting Up Samba and Configure FirewallD and SELinux to Allow File Sharing on Linux or Windows Clients.md"};function u(b,a,w,S,f,x){const i=l("Link");return m(),p("div",null,[a[30]||(a[30]=r(`<h1 id="rhce-系列-六-安裝-samba-並配置-firewalld-和-selinux-讓-linux-和-windows-共享文件" tabindex="-1">RHCE 系列（六）：安裝 Samba 並配置 Firewalld 和 SELinux 讓 Linux 和 Windows 共享文件 <a class="header-anchor" href="#rhce-系列-六-安裝-samba-並配置-firewalld-和-selinux-讓-linux-和-windows-共享文件" aria-label="Permalink to “RHCE 系列（六）：安裝 Samba 並配置 Firewalld 和 SELinux 讓 Linux 和 Windows 共享文件”">​</a></h1><p>由於計算機很少作為一個獨立的系統工作，作為一個系統管理員或工程師，就應該知道如何在有多種類型的服務器之間搭設和維護網絡。</p><p>在本篇以及該系列後面的文章中，我們會介紹用 Windows/Linux 配置 Samba 和 NFS 服務器以及 Linux 客户端。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/setup-samba-file-sharing-on-linux-windows-clients.png" alt="在 Linux 中配置 Samba 進行文件共享"></p><p><em>RHCE 系列第六部分 - 設置 Samba 文件共享</em></p><p>如果有人讓你設置文件服務器用於協作或者配置很可能有多種不同類型操作系統和設備的企業環境，這篇文章就能派上用場。</p><p>由於你可以在網上找到很多關於 Samba 和 NFS 背景和技術方面的介紹，在這篇文章以及後續文章中我們就省略了這些部分直接進入到我們的主題。</p><h3 id="步驟一-安裝-samba-服務器" tabindex="-1">步驟一： 安裝 Samba 服務器 <a class="header-anchor" href="#步驟一-安裝-samba-服務器" aria-label="Permalink to “步驟一： 安裝 Samba 服務器”">​</a></h3><p>我們當前的測試環境包括兩台 RHEL 7 和一台 Windows 8：</p><pre><code>1. Samba / NFS 服務器 [box1 (RHEL 7): 192.168.0.18], 
2. Samba 客户端 #1 [box2 (RHEL 7): 192.168.0.20]
3. Samba 客户端 #2 [Windows 8 machine: 192.168.0.106]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Testing-Setup-for-Samba.png" alt="測試安裝 Samba"></p><p><em>測試安裝 Samba</em></p><p>在 box1 中安裝以下軟件包：</p><pre><code># yum update &amp;&amp; yum install samba samba-client samba-common
</code></pre><p>在 box2：</p><pre><code># yum update &amp;&amp; yum install samba samba-client samba-common cifs-utils
</code></pre><p>安裝完成後，就可以配置我們的共享了。</p><h3 id="步驟二-設置通過-samba-進行文件共享" tabindex="-1">步驟二： 設置通過 Samba 進行文件共享 <a class="header-anchor" href="#步驟二-設置通過-samba-進行文件共享" aria-label="Permalink to “步驟二： 設置通過 Samba 進行文件共享”">​</a></h3>`,18)),e("p",null,[a[1]||(a[1]=n("Samba 這麼重要的原因之一是它為 SMB/CIFS 客户端（LCTT 譯註：SMB 是微軟和英特爾制定的一種通信協議，CIFS 是其中一個版本，更詳細的介紹可以參考 ",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Server_Message_Block"},{default:s(()=>[...a[0]||(a[0]=[n("Wiki",-1)])]),_:1}),a[2]||(a[2]=n("）提供了文件和打印設備，這使得服務器在客户端看起來就是一個 Windows 系統（我必須承認寫這篇文章的時候我有一點激動，因為這是我多年前作為一個新手 Linux 系統管理員的第一次設置）。",-1))]),a[31]||(a[31]=e("p",null,[e("strong",null,"添加系統用户並設置權限和屬性")],-1)),e("p",null,[a[4]||(a[4]=n("為了允許組協作，我們會在 box1 中用 ",-1)),t(i,{href:"http://www.tecmint.com/add-users-in-linux/"},{default:s(()=>[...a[3]||(a[3]=[n("useradd 命令",-1)])]),_:1}),a[5]||(a[5]=n("創建一個有兩個用户（user1 和 user2）的組 finance 和目錄 /finance。",-1))]),a[32]||(a[32]=e("p",null,"我們同時會把這個目錄的組所有者更改為 finance 並把權限設置為 0777（所有者和組屬主可讀可寫可執行）：",-1)),a[33]||(a[33]=e("pre",null,[e("code",null,`# groupadd finance
# useradd user1
# useradd user2
# usermod -a -G finance user1
# usermod -a -G finance user2
# mkdir /finance
# chmod 0770 /finance
# chgrp finance /finance
`)],-1)),a[34]||(a[34]=e("h3",{id:"步驟三-配置-selinux-和-firewalld",tabindex:"-1"},[n("步驟三： 配置 SELinux 和 Firewalld "),e("a",{class:"header-anchor",href:"#步驟三-配置-selinux-和-firewalld","aria-label":"Permalink to “步驟三： 配置 SELinux 和 Firewalld”"},"​")],-1)),a[35]||(a[35]=e("p",null,"在配置 /finance 作為 Samba 共享目錄之前，我們需要像下面那樣停用 SELinux 或設置恰當的布爾值和安全選項（否則，SELinux 會阻止客户端訪問共享目錄）：",-1)),a[36]||(a[36]=e("pre",null,[e("code",null,`# setsebool -P samba_export_all_ro=1 samba_export_all_rw=1
# getsebool –a | grep samba_export
# semanage fcontext –at samba_share_t "/finance(/.*)?"
# restorecon /finance
`)],-1)),e("p",null,[a[7]||(a[7]=n("另外我們必須確保 ",-1)),t(i,{href:"http://www.tecmint.com/firewalld-vs-iptables-and-control-network-traffic-in-firewall/"},{default:s(()=>[...a[6]||(a[6]=[n("firewalld",-1)])]),_:1}),a[8]||(a[8]=n(" 允許 Samba 流量通過。",-1))]),a[37]||(a[37]=r(`<pre><code># firewall-cmd --permanent --add-service=samba
# firewall-cmd --reload
</code></pre><h3 id="步驟四-配置-samba-共享目錄" tabindex="-1">步驟四： 配置 Samba 共享目錄 <a class="header-anchor" href="#步驟四-配置-samba-共享目錄" aria-label="Permalink to “步驟四： 配置 Samba 共享目錄”">​</a></h3><p>現在我們來看看配置文件 /etc/samba/smb.conf 並添加用於共享的章節（section）：我們希望組 finance 的成員可以瀏覽 /finance 的內容，在裏面保存/創建文件或者子目錄（默認權限為 0777，組所有者為 finance）：</p><p><strong>smb.conf</strong></p><hr><pre><code>[finance]
comment=Directory for collaboration of the company&#39;s finance team
browsable=yes
path=/finance
public=no
valid users=@finance
write list=@finance
writeable=yes
create mask=0770
Force create mode=0770
force group=finance
</code></pre><p>保存文件然後用 testparm 工具進行測試。如果這裏有任何錯誤，命令的輸出或提示你需要如何修復。否則，會顯示你 Samba 服務器配置的回顧：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Test-Samba-Configuration.png" alt="測試 Samba 配置"></p><p><em>測試 Samba 配置</em></p><p>如果你要添加另一個公開的共享目錄（意味着不需要任何驗證），在 /etc/samba/smb.conf 中創建另一章節，在共享目錄名稱下面複製上面的章節，只需要把 public=no 更改為 public=yes 並去掉有效用户（valid users）和寫列表（write list）命令。</p><h3 id="步驟五-添加-samba-用户" tabindex="-1">步驟五： 添加 Samba 用户 <a class="header-anchor" href="#步驟五-添加-samba-用户" aria-label="Permalink to “步驟五： 添加 Samba 用户”">​</a></h3><p>下一步，你需要添加 user1 和 user2 作為 Samba 的用户。要做到這點，你需要用 smbpasswd 命令，它會和 Samba 的資料庫進行交互。會提示你輸入一個命令用於你之後和共享目錄連接：</p><pre><code># smbpasswd -a user1
# smbpasswd -a user2
</code></pre><p>最後，重啓 Samda，並讓系統啓動時自動啓動該服務，確保共享目錄對網絡客户端可用：</p><pre><code># systemctl start smb
# systemctl enable smb
# smbclient -L localhost –U user1
# smbclient -L localhost –U user2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Verify-Samba-Share.png" alt="驗證 Samba 共享"></p><p><em>驗證 Samba 共享</em></p><p>到這裏，已經正確安裝和配置了 Samba 文件服務器。現在讓我們在 RHEL 7 和 Windows 8 客户端中測試該配置。</p><h3 id="步驟六-在-linux-中掛載-samba-共享" tabindex="-1">步驟六： 在 Linux 中掛載 Samba 共享 <a class="header-anchor" href="#步驟六-在-linux-中掛載-samba-共享" aria-label="Permalink to “步驟六： 在 Linux 中掛載 Samba 共享”">​</a></h3><p>首先，確保客户端可以訪問 Samba 共享：</p><pre><code># smbclient –L 192.168.0.18 -U user2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Mount-Samba-Share-on-Linux.png" alt="在 Linux 上掛載 Samba 共享"></p><p><em>在 Linux 上掛載 Samba 共享</em></p><p>（為 user1 重複上面的命令）</p><p>正如任何其它存儲介質，當你需要的時候你可以掛載（之後卸載）該網絡共享：</p><pre><code># mount //192.168.0.18/finance /media/samba -o username=user1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Mount-Samba-Network-Share.png" alt="掛載 Samba 網絡共享"></p><p><em>掛載 Samba 網絡共享</em></p><p>（其中 /media/samba 是一個已有的目錄）</p><p>或者在 /etc/fstab 文件中添加下面的條目以自動掛載：</p><p><strong>fstab</strong></p><hr><pre><code>//192.168.0.18/finance /media/samba cifs credentials=/media/samba/.smbcredentials,defaults 0 0
</code></pre><p>其中隱藏文件 /media/samba/.smbcredentials（它的權限被設置為 600 和 root:root）有兩行內容，指示允許使用共享的賬户的用户名和密碼：</p><p><strong>.smbcredentials</strong></p><hr><pre><code>username=user1
password=PasswordForUser1
</code></pre><p>最後，讓我們在 /finance 中創建一個文件並檢查權限和屬性：</p><pre><code># touch /media/samba/FileCreatedInRHELClient.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Create-File-in-Samba-Share.png" alt="在 Samba 共享中創建文件"></p><p><em>在 Samba 共享中創建文件</em></p><p>正如你看到的，用權限 0770 和屬主 user1:finance 創建了文件。</p><h3 id="步驟七-在-windows-上掛載-samba-共享" tabindex="-1">步驟七： 在 Windows 上掛載 Samba 共享 <a class="header-anchor" href="#步驟七-在-windows-上掛載-samba-共享" aria-label="Permalink to “步驟七： 在 Windows 上掛載 Samba 共享”">​</a></h3><p>要在 Windows 上掛載 Samba 共享，進入 ‘我的計算機’ 並選擇 ‘計算機’，‘網絡驅動映射’。下一步，為要映射的驅動分配一個驅動器盤符並用不同的認證身份檢查是否可以連接（下面的截圖使用我的母語西班牙語）：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Mount-Samba-Share-in-Windows.png" alt="在 Windows 中掛載 Samba 共享"></p><p><em>在 Windows 中掛載 Samba 共享</em></p><p>最後，讓我們新建一個文件並檢查權限和屬性：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Create-Files-on-Windows-Samba-Share.png" alt="在 Windows Samba 共享中新建文件"></p><p>在 Windows Samba 共享中新建文件</p><pre><code># ls -l /finance
</code></pre><p>這次文件屬於 user2，因為這是我們用於從 Windows 客户端中連接的賬户。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,52)),e("p",null,[a[11]||(a[11]=n("在這篇文章中我們不僅介紹瞭如何使用不同操作系統設置 Samba 服務器和兩個客户端，也介紹了",-1)),t(i,{href:"http://www.tecmint.com/configure-firewalld-in-centos-7/"},{default:s(()=>[...a[9]||(a[9]=[n("如何配置 Firewalld",-1)])]),_:1}),a[12]||(a[12]=n(" 和 ",-1)),t(i,{href:"http://www.tecmint.com/selinux-essentials-and-control-filesystem-access/"},{default:s(()=>[...a[10]||(a[10]=[n("服務器中的 SELinux",-1)])]),_:1}),a[13]||(a[13]=n(" 以獲取所需的組協作功能。",-1))]),e("p",null,[a[15]||(a[15]=n("最後，同樣重要的是，我推薦閲讀網上的 ",-1)),t(i,{href:"https://www.samba.org/samba/docs/man/manpages-3/smb.conf.5.html"},{default:s(()=>[...a[14]||(a[14]=[n("smb.conf man 手冊",-1)])]),_:1}),a[16]||(a[16]=n(" ，查看其它比本文中介紹的場景更加合適你的場景的配置命令。",-1))]),a[38]||(a[38]=e("p",null,"正如往常，歡迎在下面的評論框中留下你的評論或建議。",-1)),a[39]||(a[39]=e("hr",null,null,-1)),e("p",null,[a[18]||(a[18]=n("via: ",-1)),t(i,{href:"http://www.tecmint.com/setup-samba-file-sharing-for-linux-windows-clients/"},{default:s(()=>[...a[17]||(a[17]=[n("http://www.tecmint.com/setup-samba-file-sharing-for-linux-windows-clients/",-1)])]),_:1})]),e("p",null,[a[22]||(a[22]=n("作者：",-1)),t(i,{href:"http://www.tecmint.com/author/gacanepa/"},{default:s(()=>[...a[19]||(a[19]=[n("Gabriel Cánepa",-1)])]),_:1}),a[23]||(a[23]=n(" 譯者：",-1)),t(i,{href:"http://www.mutouxiaogui.cn/blog/"},{default:s(()=>[...a[20]||(a[20]=[n("ictlyh",-1)])]),_:1}),a[24]||(a[24]=n(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:s(()=>[...a[21]||(a[21]=[n("wxy",-1)])]),_:1})]),e("p",null,[a[27]||(a[27]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...a[25]||(a[25]=[n("LCTT",-1)])]),_:1}),a[28]||(a[28]=n(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:s(()=>[...a[26]||(a[26]=[n("Linux中國",-1)])]),_:1}),a[29]||(a[29]=n(" 榮譽推出",-1))])])}const C=o(d,[["render",u]]);export{L as __pageData,C as default};
